expressionInfo.expression:
// fields: $feature.name $feature.forest $feature.classification $feature.elevation_ft $feature.aspect_deg $feature.pal $feature.pal_raw $feature.pal_rank $feature.erc $feature.ic $feature.fc_dates $feature.fc_pal $feature.fc_type $feature.forest_pal_station $feature.report_time
var C = {'A':'#2ecc71','B':'#a8d92e','C':'#f1c40f','D':'#e67e22','Ev':'#e74c3c','E':'#8e2424'};
function col(p) { if (IsEmpty(p) || !HasKey(C, p)) { return '#bbbbbb'; } return C[p]; }
function fv(k) { if (HasKey($feature, k)) { return $feature[k]; } return null; }
var p = fv('pal');
var h = '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">' +
  '<span style="min-width:48px;text-align:center;padding:4px 10px;border-radius:5px;background:' + col(p) +
  ';color:#fff;font-weight:bold;font-size:22px">' + DefaultValue(p, '–') + '</span>' +
  '<div><b>Project Activity Level</b><br><span style="font-size:12px">ERC ' + DefaultValue(fv('erc'), '–') +
  ' · IC ' + DefaultValue(fv('ic'), '–') + ' (1400 obs)</span></div></div>';
var ov = fv('pal_override');
if (!IsEmpty(ov)) {
  var oc = fv('override_comment'); var ob = fv('override_by');
  var note = '★ Adjusted PAL ' + ov + ' (calculated ' + DefaultValue(fv('pal_raw'), '–') + ') until ' + fv('override_until');
  if (!IsEmpty(oc)) { note += ' — ' + oc; }
  if (!IsEmpty(ob)) { note += ' (' + ob + ')'; }
  h += '<div style="font-size:12px;background:#fff4d6;padding:4px 6px;border-radius:4px;margin-bottom:6px">' + note + '</div>';
}
if (!IsEmpty(fv('fc_dates'))) {
  var d = Split(fv('fc_dates'), ','); var pp = Split(fv('fc_pal'), ','); var tt = Split(fv('fc_type'), ',');
  var today = Text(ChangeTimeZone(Now(), 'America/Los_Angeles'), 'YYYY-MM-DD');
  var r1 = ''; var r2 = '';
  for (var i in d) {
    var dt = Date(Number(Left(d[i], 4)), Number(Mid(d[i], 5, 2)) - 1, Number(Right(d[i], 2)));
    var bd = IIf(d[i] == today, 'border:2px solid #000;', 'border:1px solid #fff;');
    r1 += '<td style="text-align:center;font-size:10px;padding:1px">' + Text(dt, 'ddd') + '<br>' + Text(dt, 'M/D') + '</td>';
    r2 += '<td style="text-align:center;padding:2px 1px;' + bd + 'background:' + col(pp[i]) + ';color:#fff;font-weight:bold;font-size:12px">' +
          pp[i] + '<br><span style="font-size:9px;font-weight:normal">' + IIf(tt[i] == '-', '', tt[i]) + '</span></td>';
  }
  h += '<div style="font-size:12px;font-weight:bold;margin:4px 0 2px">13-day PAL (O = observed, F = forecast)</div>' +
       '<table style="border-collapse:collapse;width:100%"><tr>' + r1 + '</tr><tr>' + r2 + '</tr></table>';
}
h += '<div style="font-size:11px;color:#666;margin-top:6px">' + DefaultValue(fv('forest'), 'Not a forest PAL station') +
     ' · ' + DefaultValue(fv('classification'), '') + ' · ' + Round(DefaultValue(fv('elevation_ft'), 0), 0) + ' ft<br>' +
     'Source: <a href="https://gacc.nifc.gov/oscc/predictive/weather/pal_combined_report.html" target="_blank">CA PAL Combined Report</a>, generated ' +
     DefaultValue(fv('report_time'), '') + '</div>';
return { type: 'text', text: h };
